<script setup lang="ts">
import{ref}from'vue';import{useRouter}from'vue-router';import{useAuthStore}from'../stores/auth';import{passwordPolicyError}from'../auth/password-policy'
const auth=useAuthStore(),router=useRouter(),current=ref(''),next=ref(''),confirm=ref(''),busy=ref(false),error=ref('')
async function save(){error.value='';const issue=passwordPolicyError(next.value);if(issue){error.value=issue;return};if(next.value!==confirm.value){error.value='两次新密码不一致';return};busy.value=true;try{await auth.changePassword(current.value,next.value,confirm.value);current.value='';next.value='';confirm.value='';await router.replace('/login')}catch(e){error.value=e instanceof Error?e.message:'密码更新失败'}finally{busy.value=false}}
async function logout(){await auth.logout();await router.replace('/login')}
</script>
<template><main class="mandatory-reset"><section class="panel"><h1>必须设置新密码</h1><p>当前使用服务器启动日志中的临时密码。它仅在30分钟内有效，设置新密码前不能进入工作台。</p><el-alert v-if="error" :title="error" type="error" :closable="false"/><form class="connection-form" @submit.prevent="save"><label for="temporary-password">当前临时密码</label><el-input id="temporary-password" v-model="current" type="password" show-password autocomplete="current-password" :maxlength="20"/><label for="mandatory-new-password">新密码</label><el-input id="mandatory-new-password" v-model="next" type="password" show-password autocomplete="new-password" :maxlength="20"/><p class="field-hint">6–20 个字符，不能与临时密码相同。</p><label for="mandatory-confirm-password">确认新密码</label><el-input id="mandatory-confirm-password" v-model="confirm" type="password" show-password autocomplete="new-password" :maxlength="20"/><el-button type="primary" native-type="submit" :loading="busy" :disabled="!current||!next||!confirm">设置新密码并重新登录</el-button><el-button :disabled="busy" @click="logout">退出</el-button></form></section></main></template>
<style scoped>.mandatory-reset{min-height:100dvh;display:grid;place-items:center;padding:24px;background:var(--page-bg,#f2f5f7)}.panel{width:100%;max-width:520px;padding:32px}.panel>p{line-height:1.8;color:var(--muted);margin:16px 0 24px}.connection-form{gap:12px}</style>
